INSERT INTO `beneficios` VALUES (50, 'HONOR X9C 5G', 41, NULL, 'Adquiere el HONOR X9C 5G 8GB + 256GB\r\n💰 Inicial: S/ 400\r\n💳 Cuotas: S/ 155 \r\n\r\nMás velocidad con tecnología 5G ⚡\r\nMás rendimiento para producir más.\r\n\r\n🚀 Si quieres lo mejor, este es para ti.', 400.00, 7, 155.00, NULL, NULL, NULL, NULL, 'img/beneficios/beneficio_1771030013_698fc5fd73f8d.png', 1, '2026-02-13 18:46:53', '2026-02-13 18:46:53', NULL);
INSERT INTO `beneficios` VALUES (51, 'MECÁNICA/MOTORES/PLANCHADO Y PINTURA', 42, 0, 'ERES CLIENTE O FLOTA? CREDIGO TE BRINDA :\r\n🔧 Mecánica y motores\r\n🚗 Planchado y pintura\r\n✅ Diagnóstico y reparación\r\n✅ Motores a punto\r\n✅ Pintura impecable\r\n\r\nTambién destaca una oferta de pago:\r\n🔥 Solo 30% de inicial\r\n📅 Hasta en 5 cuotas\r\nPREVIA CITA EN NUESTRAS OFICINAS AQPGO\r\nPRECIOS VARÍAN DE ACUERDO A LA COTIZACIÓN', 0.00, 5, 60.00, NULL, 'S/.', NULL, 'semanal', 'img/beneficios/beneficio_1771415430_6995a78679290.png', 1, '2026-02-18 05:50:30', '2026-02-21 17:27:55', NULL);
INSERT INTO `beneficios` VALUES (52, 'CREDI YANGO JETOUR X70 FULL', 45, NULL, '✅JETOURS X70 :🚗👍🏻🔥🔥\r\n✅Solo GLP  🚗👍🏻🔥🔥\r\n✅Cuota inicial : $3000 inicial\r\n✅Total de semanas : 200 semanas.\r\n✅Pagos semanales de : $110.\r\n✅ ¡Incluye GPS! 📍\r\n🚗👍🏻🔥🔥🚗👍🏻🔥🔥🚗👍🏻🔥🔥\r\n¡Tu JETUOR X70 Full M/T te está esperando!\r\n\r\nNo dejes pasar esta oportunidad de tener tu propio auto con cuotas accesibles \r\n\r\nFináncialo con cuotas semanales accesibles.', 3000.00, 200, 110.00, NULL, NULL, NULL, NULL, 'img/beneficios/beneficio_1771444893_69961a9d0c6fe.png', 1, '2026-02-18 14:01:33', '2026-02-18 14:01:33', NULL);
INSERT INTO `beneficios` VALUES (53, 'PLANCHADO Y PINTURA, ACCESORIOS, POLARIZADOS, PULIDO Y MÁS', 42, 0, '🔧 Dale a tu vehículo el cuidado que merece 🔧\r\n\r\nEn D&L Soluciones Automotrices tenemos todo lo que tu auto necesita:\r\n\r\n✔️ Planchado y pintura profesional\r\n✔️ Restauraciones\r\n✔️ Pulido y tratamiento cerámico\r\n✔️ Detailing\r\n✔️ Tapizados\r\n✔️ Polarizados y control solar\r\n✔️ Protección de bajos\r\n✔️ Accesorios y repuestos\r\n\r\n📍 Previa cita en OFICINA AREQUIPA GO\r\nPRECIOS VARÍAN DE ACUERDO A LA COTIZACIÓN', 0.00, 5, 60.00, NULL, 'S/.', NULL, 'semanal', 'img/beneficios/beneficio_1771716041_699a3dc99cca7.png', 1, '2026-02-21 17:20:41', '2026-02-21 17:28:08', NULL);
