INSERT INTO `cupones` VALUES (10, 'Descuento Opticas', 'Ten el mejor beneficio en examen de la vista y mas de 300 modelos de lentes para UD y su familia !!\r\nllamar al 973398373 o visitenos en nuestro local calle la merced 125 cercado', 'porcentaje', 30.00, 'img/cupones/cupon_68d173a7708e62.11576346.jpeg', '2025-09-15', '2026-12-31', 1, NULL, 1, 'exclusivo', '2025-09-15 13:14:07', '2026-01-23 11:36:03', 8);
INSERT INTO `cupones` VALUES (11, 'Taller de planchado y pintura D&L', 'Planchado y pintura profesional al horno.           \r\n*Planchado con tecnología Pin-Puller.                            \r\n*Retoques invisibles.        \r\n*Cambio de color.           \r\n*Pintura por paños           \r\n*Pulido profesional 3M.    \r\n*Aplicación de antigravilla.\r\n*Undercoating a chasis.  \r\n*Cromado de accesorios\r\n*Hidrografia pintura Hidrográfica.                     \r\n*Restauración con soldadura MIG.                    \r\n*Mucho mas.        \r\n  SOLICITA TU COTIZACION SIN COMPROMISO.  957479800    \r\n Ubicanos aqui en av dolores 122 cercado \r\nAceptamos todo tipo de trajetas.\r\nContactanos al watshapp aqui https://wa.me/51957479800\r\n Porque nuestro profesionalismo nos hace diferentes', 'porcentaje', 10.00, 'img/cupones/cupon_68c8aafcc932e8.86282369.jpeg', '2025-09-16', '2026-12-31', 1, NULL, 1, 'exclusivo', '2025-09-15 19:10:36', '2026-01-23 11:36:53', 8);
INSERT INTO `cupones` VALUES (14, 'Refiere y Gana', '🏠 ¿Conoces a alguien que quiera comprar o vender una propiedad? ¡Gana dinero recomendando! 💰\r\n\r\nAhora puedes afiliarte GRATIS a nuestro programa y empezar a generar ingresos extra por cada venta concretada gracias a tus referidos.\r\n\r\n✅ ¿Tienes amigos, familiares o conocidos buscando casa o queriendo vender?\r\n✅ Solo necesitas dejarnos tus datos y referirlos\r\n✅ Nosotros hacemos el trabajo, tú ganas una comisión por la venta cerrada\r\n\r\n📲 Afíliate hoy, sin compromiso, y empieza a ganar desde tu red de contactos.\r\n\r\n🔗 [Deja tus datos y los de tus referidos aquí y comienza a generar ingresos] (inserta enlace o llamada a la acción)\r\n\r\n💼 ¡Conviértete en nuestro socio y aprovecha el movimiento del mercado inmobiliario!\r\ntelefono: 970537473\r\nhttps://wa.me/message/AJAPHASPSDJZL1', 'monto_fijo', 200.00, 'img/cupones/cupon_68cacdbae6b731.20347451.jpeg', '2025-09-17', '2026-02-28', 100, 200, 0, 'exclusivo', '2025-09-17 10:03:22', '2026-03-10 12:43:52', 8);
INSERT INTO `cupones` VALUES (15, 'Taller Formula Motors', '\"Fórmula MOTORS entiende que tu vehículo es tu herramienta de trabajo. Por eso, ofrecemos un servicio rápido y eficiente de planchado y pintura, con eficiencia y garantía, para que puedas volver a la cuidad lo antes posible y seguir trabajando sin demoras.\"', 'porcentaje', 20.00, 'img/cupones/cupon_68d427e8f372d8.96978084.jpeg', '2025-09-24', '2026-12-31', 1, NULL, 1, 'exclusivo', '2025-09-24 12:17:23', '2026-01-06 17:07:10', 8);
INSERT INTO `cupones` VALUES (21, 'GITOCA- ESCUELADE CONDUCTORES', 'S/ 50.00 soles de descuento para familiares en\r\ncualquiera de nuestros paquetes.\r\n*Estas promoción no es acumulable a otras\r\npromociones.\r\n\r\nHORARIOS DE ATENCIÓN:\r\n\r\n*Lunes a Viernes: de 8:00 am a 18:00 pm\r\n*Sábados: de 08:00 am a 17:00 pm.', 'monto_fijo', 50.00, 'img/cupones/cupon_6910250e83f9f4.31056311.png', '2025-11-09', '2026-12-31', 1, NULL, 1, 'exclusivo', '2025-11-08 23:22:22', '2026-01-06 17:06:32', 8);
INSERT INTO `cupones` VALUES (22, 'POLICLINICO SANTA CATALINA', '*Les brindamos los siguientes descuentos:\r\n10% de descuento en tu examen psicosomático.\r\n5% al 20% de descuento en tu examen\r\nocupacional o medico. (de acuerdo al perfil\r\nsolicitado)\r\n\r\n*Estas promoción no es acumulable a otras\r\npromociones.\r\n\r\nHORARIOS DE ATENCIÓN:\r\nLunes a Sábados: en horarios accesibles.', 'porcentaje', 20.00, 'img/cupones/cupon_691026d1ee6264.72674132.png', '2025-11-09', '2026-12-31', 1, NULL, 1, 'exclusivo', '2025-11-08 23:29:53', '2026-01-06 17:06:13', 8);
INSERT INTO `cupones` VALUES (23, 'EDUMIN-CENTRO DE CAPACITACIÓN', 'Beneficios tanto para sus miembros de Arequipa GO (flota) y para sus familiares directos:\r\n*50% de descuento en todos nuestros diplomados.\r\n*50% de descuento en nuestros programas y\r\ncursos de actualización y/o extensión profesional\r\nen Minería, Industria y Negocios.\r\n*30% de descuento en cursos a medida que\r\nrequieran.\r\n*30% de descuento en el diplomado que deseen\r\nllevar familiares directos.\r\n*Estas promoción no es acumulable a otras\r\npromociones.\r\nHORARIOS DE ATENCIÓN:\r\nLunes a Viernes: de 8:00 am a 19:00 pm.', 'porcentaje', 50.00, 'img/cupones/cupon_6910282ade2f26.63290035.png', '2025-11-09', '2026-12-31', 1, NULL, 1, 'exclusivo', '2025-11-08 23:35:38', '2026-01-06 17:05:59', NULL);
INSERT INTO `cupones` VALUES (24, 'DON TORIBIO CARNES Y VINOS', 'Descuentos exclusivos a miembros de Arequipa GO:\r\n\r\n*10 % de descuento en cortes nacionales.\r\n*10 % de descuento en cortes argentinos.\r\n*10 % de descuento en platos a la carta.\r\n\r\n*Estas promoción no es acumulable a otras\r\npromociones.\r\n\r\nHORARIOS DE ATENCIÓN:\r\nLunes a Domingos: de 13:00 pm a 10:30 pm', 'porcentaje', 10.00, 'img/cupones/cupon_6910299aa8bfd0.14562158.png', '2025-11-09', '2026-12-31', 1, NULL, 1, 'exclusivo', '2025-11-08 23:41:46', '2026-01-06 17:05:42', NULL);
INSERT INTO `cupones` VALUES (25, 'HOTEL COSTA SUR', 'Descuentos para miembros de Arequipa Go:\r\n\r\n*20 % de descuento en temporada baja (marzo\r\na noviembre).\r\n*10 % de descuento en temporada alta de\r\nlunes a jueves (diciembre a febrero).\r\n\r\n*Estas promoción no es acumulable a otras\r\npromociones ni fechas de año nuevo o semana\r\nsanta.\r\n\r\nHORARIOS DE ATENCIÓN\r\nLunes a Domingos: 24 horas.', 'porcentaje', 20.00, 'img/cupones/cupon_69102b27540d11.77957656.png', '2025-11-09', '2026-12-31', 1, NULL, 1, 'exclusivo', '2025-11-08 23:48:23', '2026-01-06 17:05:25', NULL);
INSERT INTO `cupones` VALUES (26, 'GITOCA S.R.L.', '35% de descuento en Recategorización de licencia de\r\nconducir del MTC..\r\n\r\n*Estas promoción no es acumulable a otras\r\npromociones.\r\n\r\nHORARIOS DE ATENCIÓN:\r\nLunes a Viernes: de 8:00 am a 18:00 pm\r\nSábados: de 08:00 am a 17:00 pm.', 'porcentaje', 35.00, 'img/cupones/cupon_69102c6ea6a0c1.44048353.png', '2025-11-09', '2027-01-31', 1, NULL, 1, 'exclusivo', '2025-11-08 23:53:50', '2026-01-06 17:05:03', NULL);
INSERT INTO `cupones` VALUES (27, 'CENTRO DE DESARROLLO INFANTIL', 'CDI Creciendo – Todas las especialidades para tu niño en un solo lugar\r\nEn CDI Creciendo ofrecemos todas las especialidades que tu niño necesita, en un único lugar y con una variedad de horarios que se adaptan a tu disponibilidad.\r\n\r\nContamos con 2 sedes en la ciudad de Arequipa, ambas equipadas con todas las especialidades y un equipo de profesionales altamente capacitadas en el trabajo infantil.\r\n\r\n✨ PROMOCIÓN ESPECIAL\r\n✔ 30% de descuento en la evaluación\r\n✔ 15% de descuento en los paquetes de terapias\r\n\r\n📞 Contáctanos al: 964 631 875\r\nEstamos aquí para ayudarte a brindar el mejor cuidado y acompañamiento para tu niño.', 'porcentaje', 30.00, 'img/cupones/cupon_693b53e4583a57.94043955.jpg', '2025-12-01', '2026-12-31', 1, NULL, 1, 'exclusivo', '2025-12-11 17:29:40', '2026-01-23 11:36:26', 8);
